<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfileGivenNameAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileGivenNameAccessor trait.
 *
 * Covers null default, string/VO assignment via withGivenName,
 * getGivenName/givenName accessors, and isGivenNameChanged with/without original.
 */
class UserProfileGivenNameAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withGivenName creates a new instance with the GivenName set
     * from a string value, and getGivenName returns the primitive string.
     */
    public function testWithGivenNameFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileGivenNameAccessorUnitTest();

        // Act
        $result = $holder->withGivenName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getGivenName());
    }
    /**
     * Asserts that withgivenName has access to the value object
     * from a string value, and getGivenName returns the primitive string.
     */
    public function testWithGivenNameFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileGivenNameAccessorUnitTest();

        // Act
        $result = $holder->withGivenName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->givenName()->value());
    }
    public function testChangedGivenName(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileGivenNameAccessorUnitTest();
        $original = $holder->withGivenName('one');
        $same = $holder->withGivenName('one');
        $modified = $holder->withGivenName('other');

        // Act
        $unchanged = $holder->isGivenNameChanged();
        $withSame = $original->isGivenNameChanged($same);
        $withDiferent = $original->isGivenNameChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfileGivenNameAccessorUnitTest
{
    use UserProfileGivenNameAccessor;
}
